package org.springframework.samples.petclinic.blackbox;

import io.restassured.http.ContentType;
import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import java.io.InputStream;
import java.nio.charset.StandardCharsets;
import java.sql.Connection;
import java.sql.DriverManager;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.Statement;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api POST /api/owners
 *
 * SecurityConfig requires a valid "Authorization: Bearer <jwt>" header for all "/api/**"
 * requests except "/api/auth/**". A token is obtained once via POST /api/auth/login.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CreateOwnerBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	private static String bearerToken() {
		String token = given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
		return "Bearer " + token;
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = CreateOwnerBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (Map.Entry<String, String> entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	@Test
	void NTC_createOwner_success_fullData(TestInfo info) throws Exception {
		String token = bearerToken();
		String body = "{\"firstName\":\"Nimbus1\",\"lastName\":\"Tester1\",\"address\":\"1 Test Way\","
				+ "\"city\":\"Madison\",\"telephone\":\"5551230001\"}";
		Integer ownerId = null;
		try {
			ownerId = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post("/api/owners")
			.then().log().all()
				.statusCode(201)
				.body("id", notNullValue())
				.body("firstName", equalTo("Nimbus1"))
				.body("lastName", equalTo("Tester1"))
				.body("address", equalTo("1 Test Way"))
				.body("city", equalTo("Madison"))
				.body("telephone", equalTo("5551230001"))
				.body("pets", equalTo(java.util.Collections.emptyList()))
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT first_name, last_name, address, city, telephone FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals("Nimbus1", rs.getString("first_name"));
				assertEquals("Tester1", rs.getString("last_name"));
				assertEquals("1 Test Way", rs.getString("address"));
				assertEquals("Madison", rs.getString("city"));
				assertEquals("5551230001", rs.getString("telephone"));
			}
		}
		finally {
			if (ownerId != null) {
				executeSqlTemplate("sql/owners-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
			}
		}
	}

	@Test
	void NTC_createOwner_success_differentCity(TestInfo info) throws Exception {
		String token = bearerToken();
		String body = "{\"firstName\":\"Nimbus2\",\"lastName\":\"Tester2\",\"address\":\"22 Second St\","
				+ "\"city\":\"Waunakee\",\"telephone\":\"5551230002\"}";
		Integer ownerId = null;
		try {
			ownerId = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post("/api/owners")
			.then().log().all()
				.statusCode(201)
				.body("id", notNullValue())
				.body("firstName", equalTo("Nimbus2"))
				.body("lastName", equalTo("Tester2"))
				.body("address", equalTo("22 Second St"))
				.body("city", equalTo("Waunakee"))
				.body("telephone", equalTo("5551230002"))
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT city FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals("Waunakee", rs.getString("city"));
			}
		}
		finally {
			if (ownerId != null) {
				executeSqlTemplate("sql/owners-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
			}
		}
	}

	@Test
	void NTC_createOwner_success_boundaryLengthNames(TestInfo info) throws Exception {
		String token = bearerToken();
		// first_name / last_name columns are VARCHAR(30) - use exactly 30 chars.
		String firstName = "N3".repeat(15);
		String lastName = "T3".repeat(15);
		String body = String.format(
				"{\"firstName\":\"%s\",\"lastName\":\"%s\",\"address\":\"3 Third Ave\",\"city\":\"Monona\",\"telephone\":\"5551230003\"}",
				firstName, lastName);
		Integer ownerId = null;
		try {
			ownerId = given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.contentType(ContentType.JSON)
				.body(body)
			.when()
				.post("/api/owners")
			.then().log().all()
				.statusCode(201)
				.body("id", notNullValue())
				.body("firstName", equalTo(firstName))
				.body("lastName", equalTo(lastName))
				.extract().path("id");

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT first_name, last_name FROM owners WHERE id = ?")) {
				ps.setInt(1, ownerId);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals(firstName, rs.getString("first_name"));
				assertEquals(lastName, rs.getString("last_name"));
			}
		}
		finally {
			if (ownerId != null) {
				executeSqlTemplate("sql/owners-create-teardown.sql", Map.of("OWNER_ID", String.valueOf(ownerId)));
			}
		}
	}

	@Test
	void ATC_createOwner_unauthorized_noHeader() {
		String body = "{\"firstName\":\"Nope\",\"lastName\":\"Nope\",\"address\":\"x\",\"city\":\"x\",\"telephone\":\"5551230009\"}";
