import java.sql.Statement;
import java.util.HashMap;
import java.util.Map;

import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;
import static org.hamcrest.Matchers.notNullValue;
import static org.hamcrest.Matchers.nullValue;
import static org.junit.jupiter.api.Assertions.assertEquals;
import static org.junit.jupiter.api.Assertions.assertNull;
import static org.junit.jupiter.api.Assertions.assertTrue;

/**
 * Black-Box API Integration Test
 *
 * @target-controller PetRestController (src/main/java/org/springframework/samples/petclinic/owner/PetRestController.java)
 * @target-api POST /api/pets
 *
 * "ownerId" has no binding annotation in the handler signature; Spring MVC's default
 * fallback resolves an unannotated simple-type argument as an implicit @RequestParam, so
 * it must be sent as a query parameter (?ownerId=...).
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class CreatePetBlackBoxTest {

	private static final String BASE_URL = System.getProperty("test.server.url", "http://localhost:8080");

	private static final String DB_URL = System.getProperty("test.db.url", "jdbc:mysql://localhost:3306/petclinic");

	private static final String DB_USER = System.getProperty("test.db.user", "petclinic");

	private static final String DB_PASSWORD = System.getProperty("test.db.password", "petclinic");

	private static Connection getDbConnection() throws Exception {
		return DriverManager.getConnection(DB_URL, DB_USER, DB_PASSWORD);
	}

	private static String bearerToken() {
		String token = given().baseUri(BASE_URL)
			.contentType(ContentType.JSON)
			.body("{\"username\":\"admin\",\"password\":\"password\"}")
		.when()
			.post("/api/auth/login")
		.then()
			.statusCode(200)
			.extract().path("token");
		return "Bearer " + token;
	}

	// Deterministic, per-method-unique ids in [921000, 921999] - dedicated range for this file.
	private int baseId(TestInfo info) {
		int h = Math.abs(info.getTestMethod().get().getName().hashCode());
		return 921000 + (h % 300);
	}

	private static void executeSqlTemplate(String resourcePath, Map<String, String> params) {
		try (Connection conn = getDbConnection();
				InputStream is = CreatePetBlackBoxTest.class.getClassLoader().getResourceAsStream(resourcePath);
				Statement stmt = conn.createStatement()) {
			String sql = new String(is.readAllBytes(), StandardCharsets.UTF_8);
			for (Map.Entry<String, String> entry : params.entrySet()) {
				sql = sql.replace("${" + entry.getKey() + "}", entry.getValue());
			}
			for (String line : sql.split("\n")) {
				String trimmed = line.trim();
				if (trimmed.startsWith("--") || trimmed.isEmpty()) {
					continue;
				}
				if (trimmed.endsWith(";")) {
					trimmed = trimmed.substring(0, trimmed.length() - 1);
				}
				if (!trimmed.isEmpty()) {
					stmt.execute(trimmed);
				}
			}
		}
		catch (Exception e) {
			throw new RuntimeException("SQL template execution failed: " + resourcePath, e);
		}
	}

	private Map<String, String> params(TestInfo info) {
		int base = baseId(info);
		Map<String, String> p = new HashMap<>();
		p.put("OWNER_ID", String.valueOf(base));
		p.put("TYPE_ID", String.valueOf(base + 1));
		p.put("TYPE_ID2", String.valueOf(base + 2));
		return p;
	}

	@Test
	void NTC_createPet_success_basic(TestInfo info) throws Exception {
		Map<String, String> p = params(info);
		int ownerId = Integer.parseInt(p.get("OWNER_ID"));
		int typeId = Integer.parseInt(p.get("TYPE_ID"));
		String token = bearerToken();
		executeSqlTemplate("sql/pets-create-teardown.sql", p);
		executeSqlTemplate("sql/pets-create-setup.sql", p);

		try {
			String body = String.format(
					"{\"name\":\"NimbusPetA\",\"birthDate\":\"2020-01-15\",\"type\":{\"id\":%d,\"name\":\"NimbusPetType\"}}",
					typeId);
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.contentType(ContentType.JSON)
				.queryParam("ownerId", ownerId)
				.body(body)
			.when()
				.post("/api/pets")
			.then().log().all()
				.statusCode(201)
				.body("name", equalTo("NimbusPetA"))
				.body("birthDate", equalTo("2020-01-15"))
				.body("type.id", equalTo(typeId))
				.body("type.name", equalTo("NimbusPetType"));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement(
							"SELECT name, birth_date, type_id, owner_id FROM pets WHERE owner_id = ?")) {
				ps.setInt(1, ownerId);
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals("NimbusPetA", rs.getString("name"));
				assertEquals("2020-01-15", rs.getDate("birth_date").toString());
				assertEquals(typeId, rs.getInt("type_id"));
				assertEquals(ownerId, rs.getInt("owner_id"));
			}
		}
		finally {
			executeSqlTemplate("sql/pets-create-teardown.sql", p);
		}
	}

	@Test
	void NTC_createPet_success_secondType(TestInfo info) throws Exception {
		Map<String, String> p = params(info);
		int ownerId = Integer.parseInt(p.get("OWNER_ID"));
		int typeId2 = Integer.parseInt(p.get("TYPE_ID2"));
		String token = bearerToken();
		executeSqlTemplate("sql/pets-create-teardown.sql", p);
		executeSqlTemplate("sql/pets-create-setup.sql", p);

		try {
			String body = String.format(
					"{\"name\":\"NimbusPetB\",\"birthDate\":\"2019-06-01\",\"type\":{\"id\":%d,\"name\":\"NimbusPetType2\"}}",
					typeId2);
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.contentType(ContentType.JSON)
				.queryParam("ownerId", ownerId)
				.body(body)
			.when()
				.post("/api/pets")
			.then().log().all()
				.statusCode(201)
				.body("name", equalTo("NimbusPetB"))
				.body("type.id", equalTo(typeId2));

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT type_id FROM pets WHERE owner_id = ? AND name = ?")) {
				ps.setInt(1, ownerId);
				ps.setString(2, "NimbusPetB");
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertEquals(typeId2, rs.getInt("type_id"));
			}
		}
		finally {
			executeSqlTemplate("sql/pets-create-teardown.sql", p);
		}
	}

	@Test
	void NTC_createPet_success_noBirthDate(TestInfo info) throws Exception {
		Map<String, String> p = params(info);
		int ownerId = Integer.parseInt(p.get("OWNER_ID"));
		int typeId = Integer.parseInt(p.get("TYPE_ID"));
		String token = bearerToken();
		executeSqlTemplate("sql/pets-create-teardown.sql", p);
		executeSqlTemplate("sql/pets-create-setup.sql", p);

		try {
			String body = String.format("{\"name\":\"NimbusPetC\",\"type\":{\"id\":%d,\"name\":\"NimbusPetType\"}}", typeId);
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.contentType(ContentType.JSON)
				.queryParam("ownerId", ownerId)
				.body(body)
			.when()
				.post("/api/pets")
			.then().log().all()
				.statusCode(201)
				.body("name", equalTo("NimbusPetC"))
				.body("birthDate", nullValue());

			try (Connection conn = getDbConnection();
					PreparedStatement ps = conn.prepareStatement("SELECT birth_date FROM pets WHERE owner_id = ? AND name = ?")) {
				ps.setInt(1, ownerId);
				ps.setString(2, "NimbusPetC");
				ResultSet rs = ps.executeQuery();
				assertTrue(rs.next());
				assertNull(rs.getDate("birth_date"));
			}
		}
		finally {
			executeSqlTemplate("sql/pets-create-teardown.sql", p);
		}
	}

	@Test
	void ATC_createPet_ownerNotFound(TestInfo info) throws Exception {
