		Map<String, String> p = params(info);
		int vetId = Integer.parseInt(p.get("VET_ID3"));
		String token = bearerToken();
		executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
		executeSqlTemplate("sql/vets-api-get-setup.sql", p);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.header("Authorization", token)
				.accept(ContentType.JSON)
			.when()
				.get("/api/vets/" + vetId)
			.then().log().all()
				.statusCode(200)
				.body("id", equalTo(vetId))
				.body("nrOfSpecialties", equalTo(2))
				.body("specialties[0].name", equalTo("nimbusdentistry"))
				.body("specialties[1].name", equalTo("nimbussurgery"));
		}
		finally {
			executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
		}
	}

