		executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
		executeSqlTemplate("sql/vets-api-get-setup.sql", p);
		try {
			given().log().all()
				.baseUri(BASE_URL)
				.accept(ContentType.JSON)
			.when()
				.get("/api/vets/" + vetId)
			.then().log().all()
				.statusCode(403);
		}
		finally {
			executeSqlTemplate("sql/vets-api-get-teardown.sql", p);
		}
	}

	@Test
	void VTC_vetId_INVALID_FORMAT() {
		String token = bearerToken();
